            NativeProviderPrincipal principal=providerPrincipal(before,principals,legacy);if(principal==null)throw retainedFailure();
            NativeRetainedWorkCapture capture=NativeRetainedWorkCapture.capture(work);credential=cipher.decrypt(before.secret);
            NativeSeparationEvidence proof=NativeSeparationEvidence.restore(capture.wire(),principal,capture.values.snapshot(),credential);
            requireRetainedOriginal(before,principal,principals,legacy,capture,work);
            NativeRetainedCompletionSemantics.Observation result=work.inspectRetainedCompletionSemantics(capture.original,proof,sourceKey,original,credential);
            requireRetainedOriginal(before,principal,principals,legacy,capture,work);
