            dispatch.requireCurrent();var manifest=dispatch.manifest;var journal=manifest.journal;var plan=manifest.plan;
            var kind=NativePrivateCustodyExchangeJournal.Kind.INVENTORY_DECISION;
            stored=journal.read(plan,kind,0);
