            var record=document.getJSONObject("observation");
            NativeRetainedAttempt.keys(record,"schema","state","inventory_native_request_id","original_request_disk_sha256",
                "original_request_document_sha256","manifest_sha256","registration_receipt_sha256",
                "read_body_base64","read_body_sha256","read_timestamp","read_attestation","http_status",
                "response_base64","response_sha256","observed_at","inventory_acknowledged","work_accepted",
                "replay_allowed","finalizer_allowed","key_removal","phone_released");
            if(!"custodial.native-original-inventory-decision-observation-record.v1".equals(record.get("schema"))
                ||!"ORIGINAL_HTTP_DECISION_DATA_NOT_NATIVE_ACK".equals(record.get("state"))
                ||!dispatch.original.nativeId.equals(record.get("inventory_native_request_id"))
                ||!dispatch.diskSha.equals(record.get("original_request_disk_sha256"))
                ||!dispatch.documentSha.equals(record.get("original_request_document_sha256"))
                ||!dispatch.manifest.manifestSha.equals(record.get("manifest_sha256"))
                ||!registrationSha.equals(record.get("registration_receipt_sha256"))
                ||!(record.get("http_status") instanceof Integer)||record.getInt("http_status")!=200)throw retainedFailure();
            for(String flag:new String[]{"inventory_acknowledged","work_accepted","replay_allowed","finalizer_allowed","key_removal","phone_released"})
                if(!Boolean.FALSE.equals(record.get(flag)))throw retainedFailure();
