        private final NativePrincipalJournal principals;
        private final NativeLegacyLineageJournal legacy;
        private final NativeRetainedAttemptJournal journal;
        private final NativeRetainedAttempt attempt;
        private NativeRetainedBatchOperation batchWitness;
